  "rootConsole.viewStrip": { area: "layout", what: "Root console window · the title bar's view strip Now / Projects / Tonight │ Mail / Calendar / To-do │ Agents / Models / Machines │ Root (one window, one frame, one ✓ pill; Ctrl+Shift+R from another view goes to Root; the root tab strip, ⚿ and ◫ appear only in the Root view)" },
  "rootConsole.subBar": { area: "layout", what: "Root console window · the Root view's tab strip, + menu, ⚿ badge and ◫ file toggle sit in a sub-bar under the title bar (a split layout keeps a strip per subwindow and no sub-bar); the Root tab shows an amber count while a root agent asks and the working ring while one works" },
  "rootConsole.emptyStart": { area: "layout", what: "Root console window · the empty Root card's \"Start <agent> in Root\" opens the default root-allowed agent in one click (or names the switch that allows it)" },
  "cockpit.rootRail": { area: "layout", what: "Root console window · a 40 px Needs-you icon rail beside the console (asking, interrupted, finished-not-seen, alerts; amber while agents ask); a click opens the full rail beside it, scrolled to that group, with push / schedule / markup groups too; fold remembered per machine; the open rail has a resize grip like Now's (width remembered per machine); with nothing waiting the 40 px column is not drawn at all and the \"Needs you 0\" chip (below) stands in the bar, so the push / schedule / markup groups stay one click away; a mouse press on it leaves the terminal's focus alone; not shown under 820 px (the chip below takes over); the same icons are Now's rail at 820–1179 px" },
  "cockpit.narrow": { area: "cockpit", what: "Root console window · narrow frames: 820–1179 px Now's Needs-you column is the icon rail (the full rail in a popover) with roster and detail side by side; under 820 px Now is master / detail (a \"Needs you N\" chip opens the rail as a popover, a click or Space on a row opens the detail, Agents / Escape on the back bar returns), Tonight and Usage stack, the title bar drops its label and folds the box filter into a ▾ icon, and Root drops its icon rail for the same \"Needs you N\" chip in its sub-bar (the rail as the same popover; a picked row goes to its tab); Tonight's Show on an item opens that agent's detail on Now (the roster is one back press away)" },
  "rootConsole.rootRow": { area: "cockpit", what: "Cockpit Now view · a root agent is an ordinary roster row with a star Root chip: Space / → draws it in the detail pane (attach-only, the Root view is not mounted then); Enter or \"Open in Root\" switches the window to Root with that tab in front, never changes the project behind and never closes the window; opening Now or Projects does not wake sleeping root terminals" },
  "overlayAgent.dock": { area: "layout", what: "OverlayAgentColumn · Ctrl+1–9 in the mail / calendar / to-do overlay docks a root agent beside the app: resizable column, ⚿ badge, ↗ open in the root console, × hide, placeholder while the console is open, Ctrl+N re-shows the same live agent, Escape stays in the agent, events/cards an agent adds fly in" },
  "rootConsole.tabMenu": { area: "layout", what: "RootOverlay · right-clicking a root-console tab opens the main window's tab menu: Rename, Colour, Important/Urgent, to-do card, Duplicate, Close / Close others / left / right, Reopen closed tab; colours and marks show on the console's tabs" },
  "rootConsole.installTabTitle": { area: "layout", what: "RootOverlay · a one-click install's tab pulses in the console strip until clicked" },
