  "settings.rootMcp": { area: "layout", what: "SettingsPanel · Tabtivity's tools (MCP) for root-console agents" },
  "scheduleMcp": { area: "agents", what: "Schedule MCP · local agent proposals, approval, quotas and delivery" },
  "agents.tools.group": { area: "agents", what: "Manage CLIs · grouped app tools: cockpit/help/schedule/git/markup controls plus root/web settings links, each permission independent" },
  "cockpit.mcp.rename": { area: "agents", what: "Manage CLIs · Cockpit MCP: self-only tab_rename, persistent labels and desktop/phone refresh; disable refuses existing grants" },
  "cockpit.mcp.activity": { area: "agents", what: "Cockpit · an agent's one-line activity (tab_set_activity) under its roster row: marked as the agent's own words, relative time, hidden after 30 minutes, when its machine is down and after the agent is restarted" },
  "cockpit.mcp.handoff": { area: "agents", what: "Cockpit · an agent's handoff note (tab_set_handoff) in the detail pane: summary, checks and remaining as plain text marked as the agent's report; survives restart and sync from a stale window" },
  "cockpit.mcp.results": { area: "agents", what: "Cockpit · an agent's listed results (tab_set_results) in the detail pane below the handoff: plain-text label with its project-relative path, opened only by a click through the viewer (re-checked against the project folder on the host), \"Unavailable\" for a missing file; local registered projects only" },
  "cockpit.mcp.progress": { area: "agents", what: "Cockpit · an agent's progress steps (tab_set_progress) in the detail pane below the results: pending, in progress and done as words with no spinner; a report older than 30 minutes, from a previous run of the agent or while its machine is down reads as a past report (\"was in progress\"), never as running" },
  "cockpit.mcp.blocker": { area: "agents", what: "Cockpit · an agent's reported blocker (tab_set_blocker) in place of its activity line under the roster row and in the detail pane: marked as reported by the agent, hidden after 30 minutes and after the agent is restarted, and it never changes the Needs-you count or the detected state" },
  "cockpit.mcp.verification": { area: "agents", what: "Cockpit · an agent's reported checks (tab_set_verification) in the detail pane below the progress: passed, failed, pending or not run with an optional note, worded as \"reported by the agent at <time>\" - never as verified by the app; survives restart" },
  "cockpit.mcp.attention": { area: "agents", what: "Cockpit · a question an agent reports for its own tab (tab_request_attention) in the Needs-you list as \"Agent asks\", in the header badge and in the detail pane: counted once with the app-detected asking state of the same tab, opens that tab's conversation, Dismiss hides it for good without answering or approving anything; gone after 24 hours, a restart of the agent or the tab closing" },
  "cockpit.mcp.milestones": { area: "agents", what: "Cockpit · an agent's finished milestones (tab_add_milestone) in the detail pane and in Tonight's \"While you were away\" list for the ones reported inside the away window, marked as agent-reported with the host's time; the last 20 are kept" },
  "markupMcp": { area: "agents", what: "Settings → Manage CLIs · Markup questions MCP switch (on by default): new local Claude/Codex/MCP Vibe tabs get markup_ask / markup_withdraw / markup_done; off refuses running tabs' asks and ticks" },
  "gitPushMcp": { area: "agents", what: "Git push MCP · agent push requests, fenced preflight, approval card, levels and URL confirmation; on by default at Propose; ci_runs / ci_run / ci_security_alerts reads" },
  "gitPushMcp.toDefault": { area: "agents", what: "Git push MCP · a push to the remote's default branch (main) is no longer refused: it is always staged as a card, even at Apply, with a \"default branch\" line; a listed protected branch is still refused" },
  "gitPushMcp.settled": { area: "agents", what: "Git bar / Agents view · a push card the system closed (a newer request, the remote already holding the commit - confirmed by ls-remote from the refresh, the agent's withdrawal) stays listed with its reason and a Clear button; a card with the changed-file list (workflow, hook and manifest paths first), the file count on a default-branch card, and subjects stripped of invisible characters" },
  "gitPushMcp.ciAllow": { area: "agents", what: "Git bar / Agents view · \"Allow CI for <owner/repo>\" card (gap 19): an agent's CI read of a repo that is not the confirmed push repo is refused (ci_repo_unconfirmed) and stages this card; Allow records the repo in projects.json git_ci_repos, Dismiss refuses; a repo made after the tab started answers repo_changed" },
  "mcpSecurity.headless": { area: "agents", what: "MCP session access · note on tabs Mobile started with no window (#2339): such a tab gets the schedule, git and help MCP servers from the Mobile host's own listener (`/mcp` in the tab lists them); a schedule proposal it makes waits in agent_tasks.json and shows in the window (at once if one is open, via the refresh poke); its git_push / git_release answer window_required; its sessions are not listed in this panel" },
  "gitRelease": { area: "files", what: "Release button in the git bar + agent git_release card · annotated tag on the pushed tip, one-tag push, version suggestion, refused while the tip's GitHub CI runs or is red (ci_pending/ci_failed)" },
  "setDefaultApp.patch": { area: "files", what: "Set default app dialog (global scope) and Settings → File types · each change is saved as a patch of one entry (`patch_default_apps`, under the file's lock), not the whole map, so two windows or the phone saving at once keep each other's entries; falls back to the whole save on an older backend" },
  "settings.rootMcpLocalOnly": { area: "layout", what: "SettingsPanel · Only local models get these tools" },
  "settings.rootMcpMail": { area: "layout", what: "SettingsPanel · Agents get Tabtivity's mail tools" },
  "settings.rootMcpMailLocalOnly": { area: "layout", what: "SettingsPanel · Only local models get the mail tools" },
  "settings.rootMcpMailLocalRead": { area: "layout", what: "SettingsPanel · Local models may read the mails you share (marked only, loopback Ollama, writes staged after a read)" },
  "settings.terminalWebgl": { area: "layout", what: "SettingsPanel · WebGL terminal renderer" },
  "settings.gpuCompositing": { area: "layout", what: "SettingsPanel · GPU compositing (Linux, after a restart: DMA-BUF renderer on, 2D canvas acceleration off on every webview; PDFs complete, smooth scroll, no flicker or renderer crash)" },
